content.text:
{
  "name": "Tango设备连接器",
  "name_en": "Tango Device Connector",
  "manufacturer": "",
  "description": "一个用于实验控制软件的非物理组件，用来依据 Tango 资源定位符连接 Tango 设备服务器，并按类型注解自动创建子设备或信号。它支持真实连接与模拟连接，适合将基于 Tango Controls 的实验仪器统一接入异步控制流程。",
  "description_en": "A non-physical software component for laboratory control systems that connects to Tango device servers using a Tango resource locator and can automatically create child devices or signals from annotations. It supports both real and mock connections, helping integrate Tango Controls-based instruments into an asynchronous experiment workflow.",
  "actions": [
    {
      "action_name": "auto-set_trl",
      "description": "设置 Tango 资源定位符（TRL）。",
      "description_en": "Set the Tango resource locator (TRL)."
    },
    {
      "action_name": "auto-create_children_from_annotations",
      "description": "根据类型注解创建子设备或信号。",
      "description_en": "Create child devices or signals from type annotations."
    },
    {
      "action_name": "auto-connect_mock",
      "description": "连接到模拟 Tango 设备，并为子项建立模拟连接结构。",
      "description_en": "Connect to a mock Tango device and create the mock child connection structure."
    },
    {
      "action_name": "auto-connect_real",
      "description": "连接到真实 Tango 设备服务器，并按需要自动填充子设备或信号。",
      "description_en": "Connect to a real Tango device server and auto-populate child devices or signals as needed."
    }
  ],
  "tag_hints": [
    "Tango Controls",
    "device connection",
    "Tango resource locator",
    "annotation-based child creation",
    "mock device connection",
    "async device proxy"
  ]
}

